@startuml

class H2S_Organization {}

class City {}

class Location {}

class DistributionCenter {}

class FoodBank {}

class Resident {
  + name : string
  + streetAddress : string
  + phoneNumber : string
  + email : string
  + itemDescription : string
}

class PickupRequest {
  + requestedDate : date
  + pickupTimeWindow : string
}

class Vehicle {
  + vehicleNumber : string
  + storageCapacity : float
}

class VolunteerDriver {
  + name : string
  + availableDays : string[]
}

class PickupRoute {
  + routeDate : date
}

class Item {
  + description : string
  + weight : float
  + dimensions : string
  + category : string
  + isFood : boolean
  + rfidTag : string
}

class H2S_Employee {
  + name : string
}

class Client {
  + name : string
  + homeAddress : string
  + neededCategories : string[]
}

class Delivery {
  + deliveryDate : date
}

H2S_Organization "1" *-- "*" City
City "1" *-- "1..*" Location
Location "1" *-- "0..1" DistributionCenter
Location "1" *-- "0..1" FoodBank

Resident "1" -- "0..*" PickupRequest
PickupRequest "1" *-- "1..*" Item
PickupRequest "*" -- "1" Location : pickupLocation

VolunteerDriver "1" -- "0..*" PickupRoute
Vehicle "1" -- "0..*" PickupRoute
PickupRoute "1" *-- "1..*" Item : scheduledItems

Item "*" -- "1" DistributionCenter : receivedAt
Item "*" -- "1" H2S_Employee : processedBy

H2S_Employee "1" -- "*" Item : assignsCategory
H2S_Employee "1" -- "*" Client : calls

Client "1" -- "0..*" Delivery
Delivery "1" *-- "1..*" Item
VolunteerDriver "1" -- "0..*" Delivery : performsDelivery

class CategoryList {}
Item "1" -- "1" CategoryList : belongsTo

@enduml

